/**
 * Mark a path to be deleted when the filesystem is closed.
 * Unlike the superclass, no existence probe of the path is made:
 * for an object store that would be an extra HTTP request, and the
 * deletion during {@link #close()} is robust to missing paths.
 * @param f the path to delete.
 * @return true, always.
 * @throws IOException IO failure
 */
@Override
public boolean deleteOnExit(Path f) throws IOException {
  Path qualifiedPath = makeQualified(f);
  synchronized (deleteOnExit) {
    deleteOnExit.add(qualifiedPath);
  }
  return true;
}

/**
 * Cancel the scheduled deletion of the path when the filesystem is closed.
 * @param f the path to cancel deletion
 * @return true if the path was found in the delete-on-exit list.
 */
@Override
public boolean cancelDeleteOnExit(Path f) {
  Path qualifiedPath = makeQualified(f);
  synchronized (deleteOnExit) {
    return deleteOnExit.remove(qualifiedPath);
  }
}

/**
 * Delete all paths that were marked as delete-on-exit. This recursively
 * deletes all files and directories in the specified paths. It does not
 * check if the file exists, nor does it check whether the filesystem is
 * closed: the deletion happens as part of the close sequence, and so
 * {@link #deleteWithoutCloseCheck(Path, boolean)} is used.
 *
 * The time to process this operation is {@code O(paths)}, with the actual
 * time dependent on the time for the deletion operations to complete,
 * successfully or not.
 */
@Override
protected void processDeleteOnExit() {
  synchronized (deleteOnExit) {
    for (Iterator<Path> iter = deleteOnExit.iterator(); iter.hasNext();) {
      Path path = iter.next();
      try {
        deleteWithoutCloseCheck(path, true);
      } catch (IOException e) {
        LOG.info("Ignoring failure to deleteOnExit for path {}", path);
        LOG.debug("The exception raised when deleting {}", path, e);
      }
      iter.remove();
    }
  }
}

